ALTER TABLE "onboarding_audit_events" ADD CONSTRAINT "onboarding_audit_events_reopened_check" CHECK ("onboarding_audit_events"."event_type" <> 'reopened' or ("onboarding_audit_events"."from_status" is not null and "onboarding_audit_events"."from_status" = 'approved' and "onboarding_audit_events"."to_status" = 'review_needed' and "onboarding_audit_events"."version" is not null));--> statement-breakpoint
ALTER TABLE "onboarding_audit_events" ADD CONSTRAINT "onboarding_audit_events_event_type_check" CHECK ("onboarding_audit_events"."event_type" in ('submitted', 'review_requested', 'resubmitted', 'blocked', 'unblocked', 'approved', 'reopened'));--> statement-breakpoint
ALTER TABLE "onboarding_audit_events" ADD CONSTRAINT "onboarding_audit_events_actor_kind_check" CHECK (("onboarding_audit_events"."event_type" in ('submitted', 'resubmitted') and "onboarding_audit_events"."member_user_id" is not null) or ("onboarding_audit_events"."event_type" in ('review_requested', 'blocked', 'unblocked', 'approved', 'reopened') and "onboarding_audit_events"."reviewer_user_id" is not null));--> statement-breakpoint
ALTER TABLE "onboarding_review_actions" ADD CONSTRAINT "onboarding_review_actions_action_check" CHECK ("onboarding_review_actions"."action" in ('blocked', 'unblocked', 'reopened'));--> statement-breakpoint
ALTER TABLE "onboarding_review_actions" ADD CONSTRAINT "onboarding_review_actions_reason_code_check" CHECK (("onboarding_review_actions"."action" = 'blocked' and "onboarding_review_actions"."reason_code" in ('critical_basis_missing', 'rights_not_cleared', 'requires_extra_work')) or ("onboarding_review_actions"."action" = 'unblocked' and "onboarding_review_actions"."reason_code" in ('basis_provided', 'rights_cleared', 'extra_work_agreed')) or ("onboarding_review_actions"."action" = 'reopened' and "onboarding_review_actions"."reason_code" in ('material_input_change', 'rights_or_asset_change', 'scope_or_strategy_change')));